// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address deployer) public {
        vm.assume(deployer != address(0));
        // Deploy a new C with deployer as stakingToken and distributor, then check owner
        vm.prank(deployer);
        C c2 = new C(deployer, deployer);
        assertTrue(c2.owner() == deployer);
    }
}

